do $do$
declare spec jsonb := $j${"m":{"Licencias":["id","negocio","giro","dueno","whatsapp","registro","vencePrueba","estado","usuarios","ultimaConexion","hojaId","plus","notas","ultimaVenta","ventas7","version","etiqueta","contab","llegoPor","giros","persona","cobro","origen","vid"],"Accesos":["whatsapp","negocioId","usuarioId","activo"],"Soporte":["id","negocioId","negocio","dueno","whatsapp","motivo","modulo","estado","version","diaPrueba","ultimo","ultimoTexto","deCliente","sinLeerAdm","sinLeerCli","creado"],"SoporteMsg":["id","chatId","de","texto","foto","quien","fecha"],"Seguimiento":["id","negocioId","tipo","fecha","nota"],"PagosLic":["id","negocioId","fecha","monto","concepto","metodo","nota"],"CuotasLic":["id","negocioId","fecha","monto","concepto","gracia","estado","pagoId","pagadaEl","nota","creado"],"GastosPanel":["id","fecha","tipo","plataforma","nombre","desde","hasta","moneda","montoOrig","tasa","monto","nota","anulado","creado"],"Contratos":["id","negocioId","fecha","titulo","texto","monto","desde","hasta","estado","firma","firmadoEl","firmadoPor","huella","pdfId","creado"],"Visitas":["id","fecha","pagina","origen","disp","vid","ref"]},"n":{"Usuarios":["id","usuario","nombre","rol","color","hash","salt","activo","creado","sucursal"],"Productos":["id","codigo","nombre","categoria","tipo","unidad","precio","costo","margen","stock","stockMin","tasaIsv","icono","foto","fotoFecha","descripcion","tienda","activo","creado","opciones","plataforma","entrega","incluye","caduca","garantia","giro"],"PlanCuentas":["id","codigo","nombre","tipo","naturaleza","padre","activo","creado"],"Asientos":["id","numero","fecha","tipo","concepto","lineas","ref","usuarioId","anulado","anulacion","creado"],"Conciliacion":["id","mes","saldoBanco","marcados","nota","actualizado","listo"],"Cuentas":["id","plataforma","nombre","correo","clave","perfiles","costo","vence","nota","activo","creado"],"Suscripciones":["id","ventaId","clienteId","cliente","telefono","productoId","producto","plat