,"avisado","usuarioId","creado"],"Abonos":["id","fecha","clienteId","monto","metodo","aplicado","usuarioId","nota","anulado","anulacion","ref","sucursal"],"Compras":["id","numero","fecha","proveedorId","factura","total","saldo","metodo","usuarioId","anulada","nota","anulacion","sucursal"],"CompraDetalle":["id","compraId","productoId","descripcion","cantidad","costo","total","precioAnt","precio"],"Pagos":["id","fecha","proveedorId","monto","metodo","aplicado","usuarioId","nota","anulado","anulacion","sucursal"],"Gastos":["id","fechaGasto","categoria","detalle","proveedor","monto","metodo","usuarioId","nota","anulado","creado","anulacion","giro","sucursal"],"Inventario":["id","fecha","productoId","tipo","cantidad","stock","refId","usuarioId","nota","costo"],"Pedidos":["id","numero","fecha","nombre","telefono","clienteId","entrega","direccion","pago","items","subtotal","envio","total","estado","ventaId","nota","actualizado","anticipo"],"Cierres":["id","desde","hasta","usuarioId","fondo","ventas","cobros","gastos","pagos","esperado","contado","diferencia","nota","marca","sucursal"],"Distribuciones":["id","mes","tipo","destino","detalle","monto","usuarioId","nota","anulado","creado"],"Proyectos":["id","nombre","cliente","descripcion","estado","inicio","fin","margen","presupuesto","usuarioId","nota","creado","actualizado","cotizacionId","clienteId","entrega"],"ProyectoGastos":["id","proyectoId","dia","categoria","descripcion","cantidad","costoUnit","monto","productoId","caja","usuarioId","anulado","creado","anulacion","sucursal"],"ProyectoProductos":["id","proyectoId","nombre","cantidad","unidad","peso","precio","productoId","inventario","creado","estado","entregado"],"Chats":["id","telefono","nombre","clienteId","clave","productoId","producto","ultimo","ultimoTexto","deCliente","sinLeer","creado"],"Mensajes":["id","chatId","de","texto","usuarioId","fecha"],"Config":["clave","valor"]},"nums":["sinLeer","margen","precio","costo","stock","stockMin","limite","subtotal","descuento","isv","total","recibido","cambio","saldo","cantidad","monto","envio","fondo","ventas","cobros","gastos","pagos","esperado","contado","diferencia","costoUnit","peso","presupuesto","precioAnt","anticipo","garantia","temperatura","validez"],"bools":["activo","anulada","anulado","tienda","caja","deCliente"],"idx":["ventaId","clienteId","productoId","proveedorId","compraId","proyectoId","chatId","mascotaId","negocioId","fecha","numero","telefono","whatsapp","codigo"]}$j$; t text; c text; multi boolean; grupo text; cols text; pk text; ix text;
begin
  foreach grupo in array array['m','n'] loop
    multi := grupo = 'n';
    for t in select jsonb_object_keys(spec->grupo) loop
      cols := case when multi then 'negocio_id text not null references public."Licencias"("id") on delete cascade, ' else '' end;
      for c in select jsonb_array_elements_text(spec->grupo->t) loop
        cols := cols || format('%I ', c) || case when spec->'nums' ? c then 'numeric not null default 0' when spec->'bools' ? c then 'boolean not null default false' else 'text not null default ''''' end || ', ';
      end loop;
      pk := case when t = 'Config' then 'negocio_id, "clave"' when t = 'Accesos' then '"negocioId", "usuarioId"' when multi then 'negocio_id, "id"' else '"id"' end;
      execute format('create table public.%I (%s _fila bigint generated always as identity, _creado_en timestamptz not null default now(), primary key (%s))', t, cols, pk);
      execute format('alter table public.%I enable row level security', t);
      execute format('create index on public.%I (%s_fila)', t, case when multi then 'negocio_id, ' else '' end);
      for ix in select jsonb_array_elements_text(spec->'idx') loop
        if (spec->grupo->t) ? ix and position(format('%I', ix) in pk) = 0 then
          execute format('create index on public.%I (%s%I)', t, case when multi then 'negocio_id, ' else '' end, ix);
        end if;
      end loop;
    end loop;
  end loop;
end $do$;

create table public."Sesiones" (token text primary key, negocio_id text, valor text not null default '', expira timestamptz not null, _creado_en timestamptz not null default now());
alter table public."Sesiones" enable row level security;
create index on public."Sesiones" (expira);
create table public."Propiedades" (clave text primary key, valor text not null default '', actualizado timestamptz not null default now());
alter table public."Propiedades" enable row level security;
create table public."Consecutivos" (negocio_id text not null, serie text not null, valor bigint not null default 0, primary key (negocio_id, serie));
alter table public."Consecutivos" enable row level security;
create or replace function public.siguiente_consecutivo(p_negocio text, p_serie text) returns bigint
language sql security definer set search_path = public as $f$
  insert into public."Consecutivos"(negocio_id, serie, valor) values (p_negocio, p_serie, 1)
  on conflict (negocio_id, serie) do update set valor = public."Consecutivos".valor + 1
  returning valor;
$f$;
revoke all on function public.siguiente_consecutivo(text, text) from public, anon, authenticated;
